head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > chooseOptionLabel]<br/>chooseOption='true' 일때 추가되는 '선택 안내' 아이템의 Label 값을 설정합니다.",
    "validation" : [
        "useLocale='true' 이고 chooseOptionLabelLocaleRef 속성 설정 시 해당 속성은 무시됩니다.",
        "속성값 설정 시, '선택 안내' 아이템의 Label 값을 설정합니다.",
        "값을 설정하지 않으면 '-선택-' 이 적용됩니다.",
        "changeChooseOption() 메소드를 사용하여 Label 값을 동적으로 수정할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "4" },
        { "label" : "Sejong", "value" : "2" }
    ]);

    // 전제(chooseOption)는 충족값 true, 검증 대상 속성은 의미 있는 값으로 초기 선택
    con_chooseOption.setValue("2");
    con_chooseOptionLabel.setValue("도시를 선택하세요");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(DataList 순서) : Incheon(3) / Seoul(1) / Busan(4) / Sejong(2)\n- 다국어 Key websquare_name 의 텍스트 : 웹스퀘어(한국어) / WebSquare(영어)\n[절차] 조건 선택 -> Target 재생성 -> 아이템 확인 (changeChooseOption 은 Label 입력 후 실행)"', '', 'label1');

    // gdl_boolean 은 getText 로 읽는다 (미설정은 createCList 가 속성에서 제외)
    let properties = {
        chooseOption : con_chooseOption.getText(),
        useLocale : con_useLocale.getText(),
        chooseOptionLabelLocaleRef : con_chooseOptionLabelLocaleRef.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    // 특수문자(<, >, &, 큰따옴표) 포함 값은 XML 속성값으로 넘기기 위해 엔티티로 변환, 미설정이면 속성 자체를 넣지 않는다
    let cChooseOptionLabel = con_chooseOptionLabel.getValue();
    if (cChooseOptionLabel !== '') {
        let xmlLabel = cChooseOptionLabel.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
        cList += ' chooseOptionLabel="' + xmlLabel + '"';
    }

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 아이템 인덱스별 Label (Value) 와 입력창 표시값 출력 (validation 1 ~ 4)
scwin.btn_getItemInfo_onclick = function (e) {
    let arrItem = [];
    for (let i = 0; i < target1.getItemCount(); i++) {
        let item = target1.getItem(i);
        arrItem.push("[" + i + "] " + item.label + " (" + item.value + ")");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("아이템 : " + arrItem.join(" / "));
    wf_body_bottom.getObj("scwin").setReturnValue("입력창 표시값 : " + document.querySelector("[id='" + target1.id + "_label']").textContent);
};



// '선택 안내' 아이템의 Label 변경 (validation 4)
//  - changeChooseOption(newValue, newLabel) : Value 는 기본값 빈 문자열 유지
scwin.btn_changeChooseOption_onclick = function (e) {
    target1.changeChooseOption("", par_newLabel.getValue());
    scwin.btn_getItemInfo_onclick();
};
